static void ui_number(char*s,u32 n){static const u32 p[]={1000000000UL,100000000UL,10000000UL,1000000UL,100000UL,10000UL,1000UL,100UL,10UL,1UL};unsigned i,j=slen(s);int started=0;char c;for(i=0;i<10;i++){c='0';while(n>=p[i]){n-=p[i];c++;}if(c!='0'||started||i==9){s[j++]=c;started=1;}}s[j]=0;}
static int ui_output(const char*s){if(!u_live)return 0;while(*s){char c=*s++;if(c=='\n'){u_output[u_outlen]=0;if(u_outlen)ui_note(u_output);u_outlen=0;}else if(c!='\r'&&u_outlen<79)u_output[u_outlen++]=c;}return 1;}
