static UiItem*ui_items(unsigned side){return side?u_remote:u_local;}
static unsigned ui_count(unsigned side){return side?u_nr:u_nl;}
static UiItem*ui_selected(void){return u_sel[u_side]<ui_count(u_side)?ui_items(u_side)+u_sel[u_side]:0;}
static void ui_sort(UiItem*items,unsigned n){unsigned i,j;UiItem value;for(i=1;i<n;i++){value=items[i];j=i;while(j&&itemorder(value.name,value.attr,items[j-1].name,items[j-1].attr)<0){items[j]=items[j-1];j--;}items[j]=value;}}
