static int ui_path(char*out,const char*rel){unsigned n=slen(rootabs);if(n+slen(rel)+2>=64)return 0;textcopy(out,rootabs);if(rel[0]){if(n&&out[n-1]!='\\')out[n++]='\\';textcopy(out+n,rel);}return 1;}
