static void ui_queue_start(void){unsigned i;UiItem*it=ui_items(u_side);if(u_qcount&&u_qpaused){u_qpaused=0;u_view_dirty=1;ui_note("Resuming saved copy queue.");return;}if(u_qcount||u_op){ui_note("Finish or cancel the current queue first.");return;}u_qcount=u_qnext=u_qok=u_qfail=u_qdirs=0;zero(&u_tree,sizeof(u_tree));zero(u_queueattr,sizeof(u_queueattr));u_queue_side=u_side;for(i=0;i<ui_count(u_side);i++)if(it[i].tag&&valid(it[i].name)){u_queueattr[u_qcount]=it[i].attr&16;textcopy(u_queue[u_qcount++],it[i].name);}if(!u_qcount){it=ui_selected();if(it&&valid(it->name)){u_queueattr[u_qcount]=it->attr&16;textcopy(u_queue[u_qcount++],it->name);}}if(u_qcount){u_view_dirty=1;ui_note("Copy queued; folders include contents. Existing files are preserved.");}else ui_note("Select files or folders to copy.");}
